import math

def row_u(a,b,c,d):
 if a==b: return 0.
 if a>b: return row_u(b,a,d,c)
 return (b-a)*min(d/(1-a),c/b)

def evaluate(t0,t1,p0,p1,h0,h1,w):
 fn0=1-h0/p0+(1-p0)/p0*t0
 fn1=1-h1/p1+(1-p1)/p1*t1
 u=row_u(t0,t1,w*(1-p0),(1-w)*(1-p1))+row_u(fn0,fn1,w*p0,(1-w)*p1)
 e=w*((1-p0)*t0+p0*fn0)+(1-w)*((1-p1)*t1+p1*fn1)
 return e,u,t0,t1

def domain(p,h):
 return max(0,(h-p)/(1-p)),min(1,h/(1-p))

p0,p1,h0,h1,w=.3,.7,.5,.7,.5
l0,r0=domain(p0,h0); l1,r1=domain(p1,h1)
points=[]
for i in range(501):
 t0=l0+(r0-l0)*i/500
 for j in range(501):
  t1=l1+(r1-l1)*j/500
  points.append(evaluate(t0,t1,p0,p1,h0,h1,w))
points.sort()
front=[]
bestu=math.inf
for p in points:
 if p[1]<bestu-1e-12:
  front.append(p); bestu=p[1]
hull=[]
for p in front:
 while len(hull)>1:
  a,b=hull[-2:]
  cross=(b[0]-a[0])*(p[1]-b[1])-(b[1]-a[1])*(p[0]-b[0])
  if cross<=1e-12:hull.pop()
  else:break
 hull.append(p)
print('Inputs p0,p1,h0,h1,w:',p0,p1,h0,h1,w)
print('Frontier count / lower convex hull count',len(front),len(hull))
print('Hull first / last',hull[:4],hull[-4:])
for cap in [.12,.15,.2]:
 best=min((p for p in points if p[0]<=cap+1e-12),key=lambda p:p[1])
 print('Error cap / feasible best on grid',cap,best)
PY"
